<main class="dashboard-main"><header class="dashboard-header"><div class="dashboard-header-text"><h1>Meus projetos</h1><p>Visualize, edite e acompanhe os projetos publicados.</p></div><a class="botao-principal" href="publicar-projeto.php">+ Publicar projeto</a></header><section class="dashboard-section"><div class="resumo-grid"><article class="resumo-card"><strong><?= count($projetos) ?></strong><p>Projetos publicados</p></article></div></section><section class="dashboard-section"><h2>Todos os projetos</h2><?php if(empty($projetos)): ?><div class="projetos-vazio">Você ainda não possui projetos publicados.</div><?php else: ?><div class="lista-simples"><?php foreach($projetos as $p): ?><?php $pid=(int)$p['id'];$total=(int)$p['total_propostas'];$cid=(int)($p['contratacao_id']??0); ?><article class="projeto-card"><div class="projeto-card-topo"><h3><?= eMeusProj((string)$p['titulo']) ?></h3><span class="projeto-status"><?= eMeusProj($status[$p['status']]??(string)$p['status']) ?></span></div><p style="margin-top:12px;line-height:1.5;"><?= eMeusProj((string)$p['descricao_resumida']) ?></p><div class="projeto-meta" style="margin-top:16px;"><span>Categoria: <strong><?= eMeusProj($cat[$p['categoria']]??(string)$p['categoria']) ?></strong></span><span>Orçamento: <strong><?= moneyMeusProj((float)$p['orcamento_min']) ?> a <?= moneyMeusProj((float)$p['orcamento_max']) ?></strong></span><span>Prazo: <strong><?= eMeusProj(dateMeusProj((string)$p['prazo_desejado'])) ?></strong></span><span>Propostas: <strong><?= $total ?></strong></span></div><div class="acoes-inline"><a class="botao-principal" href="propostas.php?projeto=<?= $pid ?>">Ver propostas<?= $total>0?' ('.$total.')':'' ?></a><?php if(in_array($p['status'],['rascunho','aberto'],true) && $total===0): ?><a class="botao-secundario" href="editar-projeto.php?id=<?= $pid ?>">Editar projeto</a><?php endif; ?><?php if($cid>0): ?><a class="botao-secundario" href="/contratacao.php?id=<?= $cid ?>">Acompanhar contratação</a><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></section></main></div></body></html>
